insert into public.tests (id, slug, title, subtitle, test_type, section_scope, focus_domain_id, difficulty, description, sort_order) values ('31c2c16b-5053-5609-afa2-979f4b26d07e', 'week1-day1', 'Day 1 — Sentence boundaries', 'Week 1 · Standard English Conventions', 'drill', 'rw', 'standard_conventions', 'mixed', 'Day 1 of this week''s practice. Read the card first, answer untimed, then read every explanation — right or wrong.', 101) on conflict (slug) do nothing;
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('bb23dd65-9cc5-5b82-afde-5e4f4cd3c856', '31c2c16b-5053-5609-afa2-979f4b26d07e', 1, 'Day 1 — Sentence boundaries', 'rw', 923) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('5000a8f2-2241-5af5-aa0e-f09297d5c9c6', 'bb23dd65-9cc5-5b82-afde-5e4f4cd3c856', 1, 'standard_conventions', 'boundaries', 'easy', 'mc', 'Although the cane toad was introduced to Australia in 1935 to control beetle _______ quickly became a more serious pest than the insects it was meant to eat.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"pests; it"},{"key":"B","text":"pests, it"},{"key":"C","text":"pests it"},{"key":"D","text":"pests. It"}]'::jsonb, 'B', null, 'The first part begins with "Although," so it cannot stand alone — it is a dependent clause, and a dependent opener joins its sentence with a comma. A semicolon or period (choices A and D) can only separate two complete sentences, and choice C runs the clauses together with nothing at all.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('01cfbe74-6095-5eee-a2f9-28c474d702b5', 'bb23dd65-9cc5-5b82-afde-5e4f4cd3c856', 2, 'standard_conventions', 'boundaries', 'easy', 'mc', 'Marie Tharp mapped the Atlantic seafloor from ship soundings in the 1950s. Her charts revealed a vast underwater mountain _______ also showed a deep rift running along its crest.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"range; they"},{"key":"B","text":"range, they"},{"key":"C","text":"range they"},{"key":"D","text":"range, however they"}]'::jsonb, 'A', null, '"Her charts revealed a vast underwater mountain range" and "they also showed a deep rift" are both complete sentences, so they need a semicolon. Choice B is the classic comma splice, C is a run-on, and in D "however" cannot glue two sentences together with only commas.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('321e41f9-e196-5ba2-a294-695a13a95339', 'bb23dd65-9cc5-5b82-afde-5e4f4cd3c856', 3, 'standard_conventions', 'boundaries', 'easy', 'mc', 'A traditional mole sauce can demand more than twenty _______ chiles, nuts, seeds, spices, and chocolate among them.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"ingredients;"},{"key":"B","text":"ingredients"},{"key":"C","text":"ingredients:"},{"key":"D","text":"ingredients."}]'::jsonb, 'C', null, 'The words before the blank form a complete sentence, and what follows is a list that explains it — exactly the colon''s job. A semicolon or period would leave the list stranded as a fragment, and with no punctuation the sentence collides with its own list.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('a99cc66b-7ae4-5013-a4b3-b0e6a51908d2', 'bb23dd65-9cc5-5b82-afde-5e4f4cd3c856', 4, 'standard_conventions', 'boundaries', 'medium', 'mc', 'The set of more than six hundred letters that Vincent van Gogh wrote to his brother _______ scholars their most detailed record of the painter''s intentions.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"Theo, offers"},{"key":"B","text":"Theo; offers"},{"key":"C","text":"Theo: offers"},{"key":"D","text":"Theo offers"}]'::jsonb, 'D', null, 'The subject is "The set," and "offers" is its verb — nothing may separate a subject from its verb, however many words sit between them. The long subject tempts you to take a breath with a comma at choice A; the test counts on that. No punctuation is correct.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('9f86e165-1091-59c0-af1b-4bf8e77ca591', 'bb23dd65-9cc5-5b82-afde-5e4f4cd3c856', 5, 'standard_conventions', 'boundaries', 'medium', 'mc', 'The gravel road to the summit is brutal on _______ the view from the top repays every switchback.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"vehicles, but"},{"key":"B","text":"vehicles, however"},{"key":"C","text":"vehicles,"},{"key":"D","text":"vehicles"}]'::jsonb, 'A', null, 'Two complete sentences joined by "but" take a comma before the conjunction. Choice B fails because "however" is not a conjunction — it would need a semicolon or period before it. C is a comma splice and D a run-on.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('1f0691c6-0f1c-5291-ab96-941f50907507', 'bb23dd65-9cc5-5b82-afde-5e4f4cd3c856', 6, 'standard_conventions', 'boundaries', 'medium', 'mc', 'Kilauea''s 2018 eruption left the island with one unexpected _______ roughly 875 acres of new coastal land.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"gift;"},{"key":"B","text":"gift:"},{"key":"C","text":"gift"},{"key":"D","text":"gift."}]'::jsonb, 'B', null, '"Kilauea''s 2018 eruption left the island with one unexpected gift" is a complete sentence, and the phrase after the blank names what the gift was — a colon introduces exactly that kind of explanation. A semicolon or period would create a fragment, since "roughly 875 acres of new coastal land" has no verb.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('501c6904-eef5-5f3c-a540-a0c8ccafab5f', 'bb23dd65-9cc5-5b82-afde-5e4f4cd3c856', 7, 'standard_conventions', 'boundaries', 'medium', 'mc', 'Coral reefs cover less than one percent of the ocean _______ support roughly a quarter of all marine species.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"floor, however, they"},{"key":"B","text":"floor however, they"},{"key":"C","text":"floor, however they"},{"key":"D","text":"floor. However, they"}]'::jsonb, 'D', null, 'Both halves are complete sentences, and "however" belongs to the second one, so the second must start fresh after a period (a semicolon would also work, but only the period is offered). Every comma-based choice is a splice — "however" never has the power to join two sentences on its own.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('af081102-b042-5b82-a1ba-bf7fd0a9e161', 'bb23dd65-9cc5-5b82-afde-5e4f4cd3c856', 8, 'standard_conventions', 'boundaries', 'medium', 'mc', 'Deep-sea vents host animals found nowhere else, _______ tube worms taller than a person and blind shrimp that sense heat.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"including:"},{"key":"B","text":"including;"},{"key":"C","text":"including"},{"key":"D","text":"including —"}]'::jsonb, 'C', null, 'No punctuation ever follows "including" or "such as" — the word itself already does the introducing. The colon in choice A is the trap: colons introduce lists, but only directly after a complete sentence, never doubled up behind "including."') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('8f1988d7-80f0-5402-a094-b40457ddb4b2', 'bb23dd65-9cc5-5b82-afde-5e4f4cd3c856', 9, 'standard_conventions', 'boundaries', 'hard', 'mc', 'Bats are not _______ although many species rely on echolocation more than sight.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"blind,"},{"key":"B","text":"blind;"},{"key":"C","text":"blind."},{"key":"D","text":"blind:"}]'::jsonb, 'A', null, 'What follows the blank starts with "although," so it is a dependent clause and cannot stand as its own sentence — ruling out the semicolon and the period. A contrasting although-clause at the end of a sentence attaches with a comma. The colon fails because it must introduce an explanation or list, not a dependent clause.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('f4648398-6804-5e59-a3d7-17f8e5d43f25', 'bb23dd65-9cc5-5b82-afde-5e4f4cd3c856', 10, 'standard_conventions', 'boundaries', 'hard', 'mc', 'In 1898 Marie Curie noticed something her instruments could not _______ pitchblende ore was more radioactive than the uranium extracted from it.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"explain,"},{"key":"B","text":"explain"},{"key":"C","text":"explain, which"},{"key":"D","text":"explain:"}]'::jsonb, 'D', null, 'The first clause is complete, and the second clause spells out what Curie could not explain — a colon announces exactly that. Choice A is a comma splice and B a run-on; in C, "which" has nothing grammatical to attach to.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('98c719d8-97c3-596f-a84c-b4d29819a6dc', 'bb23dd65-9cc5-5b82-afde-5e4f4cd3c856', 11, 'standard_conventions', 'boundaries', 'hard', 'mc', 'After months of deliberation, the committee announced _______ that both fellowships would continue.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"on Friday,"},{"key":"B","text":"on Friday"},{"key":"C","text":"on Friday;"},{"key":"D","text":"on Friday:"}]'::jsonb, 'B', null, '"That both fellowships would continue" is the object of "announced," and no punctuation may come between a verb and its object — the short phrase "on Friday" sitting in between does not change that. The comma in choice A feels natural precisely because of the interruption; that feeling is the trap.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('b9c6f349-61e1-5991-a7d2-99423b3f9d3a', 'bb23dd65-9cc5-5b82-afde-5e4f4cd3c856', 12, 'standard_conventions', 'boundaries', 'hard', 'mc', 'Researchers finally identified the compound behind the smell of _______ a molecule released by soil bacteria when raindrops strike dry ground.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"rain; geosmin,"},{"key":"B","text":"rain geosmin,"},{"key":"C","text":"rain — geosmin,"},{"key":"D","text":"rain. Geosmin,"}]'::jsonb, 'C', null, '"Geosmin, a molecule released by soil bacteria..." has no main verb, so it is a fragment — the semicolon and period both strand it. A dash after the complete first clause introduces the naming phrase, the same job a colon would do. With nothing at all, "the smell of rain geosmin" is gibberish.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('cf1f96f2-5fce-54e9-ae9a-3531e9c4425b', 'bb23dd65-9cc5-5b82-afde-5e4f4cd3c856', 13, 'standard_conventions', 'boundaries', 'hard', 'mc', 'The exhibition gathers artifacts from three continents: bronze vessels from Anyang, in northern _______ gold masks from the Peruvian Andes; and carved ivories from the Niger Delta.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"China,"},{"key":"B","text":"China"},{"key":"C","text":"China:"},{"key":"D","text":"China;"}]'::jsonb, 'D', null, 'When list items contain commas of their own ("Anyang, in northern China"), the items themselves must be separated by semicolons — and the "; and" before the final item confirms this list is doing exactly that. A comma at the blank would blur where one item ends and the next begins.') on conflict (id) do nothing;
insert into public.tests (id, slug, title, subtitle, test_type, section_scope, focus_domain_id, difficulty, description, sort_order) values ('354c1f9f-0a63-55a2-ae71-988486c5c8ee', 'week1-day2', 'Day 2 — Commas, dashes, and pairs', 'Week 1 · Standard English Conventions', 'drill', 'rw', 'standard_conventions', 'mixed', 'Day 2 of this week''s practice. Read the card first, answer untimed, then read every explanation — right or wrong.', 102) on conflict (slug) do nothing;
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('18718368-5a15-50e7-a6c9-2ed686dcb440', '354c1f9f-0a63-55a2-ae71-988486c5c8ee', 1, 'Day 2 — Commas, dashes, and pairs', 'rw', 923) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('df347d42-6a53-513a-ae6b-6fb9de8fee57', '18718368-5a15-50e7-a6c9-2ed686dcb440', 1, 'standard_conventions', 'boundaries', 'easy', 'mc', 'The seismologist Inge Lehmann, working from earthquake records _______ that Earth has a distinct inner core.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"alone, demonstrated"},{"key":"B","text":"alone demonstrated"},{"key":"C","text":"alone; demonstrated"},{"key":"D","text":"alone: demonstrated"}]'::jsonb, 'A', null, '"Working from earthquake records alone" is a non-essential interruption that opened with a comma after "Lehmann," so it must close with a comma too — fences come in matching pairs. Choice B leaves the fence open, and a semicolon or colon cannot serve as the second half of a comma pair.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('8c273fa2-ff00-5422-abb1-d4cc26808e71', '18718368-5a15-50e7-a6c9-2ed686dcb440', 2, 'standard_conventions', 'boundaries', 'easy', 'mc', 'The novelist _______ wrote her first stories on a portable typewriter her mother bought her when she was ten.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"Octavia Butler,"},{"key":"B","text":"Octavia, Butler"},{"key":"C","text":"Octavia Butler"},{"key":"D","text":"Octavia Butler;"}]'::jsonb, 'C', null, '"The novelist" could be anyone, so the name is essential — it tells you which novelist — and essential information takes no punctuation. The comma in choice A fences off the very information the sentence depends on.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('00aac7ed-3f22-548b-afb7-e04514416d7f', '18718368-5a15-50e7-a6c9-2ed686dcb440', 3, 'standard_conventions', 'boundaries', 'easy', 'mc', 'Machu Picchu, _______ sits on a ridge nearly 8,000 feet above sea level.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"which was never found by Spanish colonizers,"},{"key":"B","text":"which was never found by Spanish colonizers"},{"key":"C","text":"that was never found by Spanish colonizers,"},{"key":"D","text":"which was never found by Spanish colonizers;"}]'::jsonb, 'A', null, 'The clause opened with a comma, so it is non-essential and must close with a comma before the sentence resumes at "sits." Choice B never closes the fence, choice D closes it with the wrong mark, and choice C uses "that" — which never follows a comma.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('f4d206df-23bc-5cb2-a0b2-7f938cd472ee', '18718368-5a15-50e7-a6c9-2ed686dcb440', 4, 'standard_conventions', 'boundaries', 'medium', 'mc', 'The ingredients — flour, water, salt, and _______ have not changed in a thousand years.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"yeast,"},{"key":"B","text":"yeast —"},{"key":"C","text":"yeast;"},{"key":"D","text":"yeast"}]'::jsonb, 'B', null, 'The list opened with a dash, so it must close with a dash: fences match. Choice A is the classic mixed pair — dash on the way in, comma on the way out — and it is wrong every single time.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('1f303ae9-ad92-5536-ad3c-dabaf14b6110', '18718368-5a15-50e7-a6c9-2ed686dcb440', 5, 'standard_conventions', 'boundaries', 'medium', 'mc', 'Her second symphony, completed in only six _______ established her reputation across Europe.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"weeks —"},{"key":"B","text":"weeks;"},{"key":"C","text":"weeks"},{"key":"D","text":"weeks,"}]'::jsonb, 'D', null, '"Completed in only six weeks" opened with a comma, so a comma must close it — lift the phrase out and "Her second symphony established her reputation" works perfectly. The dash in choice A mixes fence types, and with choice C the phrase never ends.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('30f19176-0be1-5559-aa96-a153a7ed00e9', '18718368-5a15-50e7-a6c9-2ed686dcb440', 6, 'standard_conventions', 'boundaries', 'medium', 'mc', 'The museum owns forty antique clocks, and most have long since stopped. The only one _______ still keeps accurate time was assembled in 1763.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"that"},{"key":"B","text":"that,"},{"key":"C","text":", which"},{"key":"D","text":", which,"}]'::jsonb, 'A', null, 'The clause is essential — it tells you WHICH of the forty clocks — so it takes "that" with no comma. Lift-out test on choice D: "The only one was assembled in 1763" no longer says which clock, and the museum owns forty. Choices B and C each leave a stray comma.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('57e85f98-ddaf-58b5-a51c-3e11ea1808c9', '18718368-5a15-50e7-a6c9-2ed686dcb440', 7, 'standard_conventions', 'boundaries', 'medium', 'mc', 'The results, _______ pointed the other way: the treated fields yielded less.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"however"},{"key":"B","text":"however,"},{"key":"C","text":"however;"},{"key":"D","text":"however:"}]'::jsonb, 'B', null, '"However" interrupts the sentence mid-stream, so it is fenced by a pair of commas — one before it (already in the text) and one after it. A semicolon or colon cannot close a comma fence, and choice A leaves the interruption dangling open.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('c50a20ed-e502-5064-a637-83f79f7c952e', '18718368-5a15-50e7-a6c9-2ed686dcb440', 8, 'standard_conventions', 'boundaries', 'medium', 'mc', 'The expedition left from Portsmouth, _______ on a gray morning in June.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"England,"},{"key":"B","text":"England"},{"key":"C","text":"England;"},{"key":"D","text":"England —"}]'::jsonb, 'A', null, 'A country (or state) after a city is treated as non-essential: fenced by commas on both sides — "Portsmouth, England," — before the sentence continues. Choices B, C, and D all fail to close the comma that opened after "Portsmouth."') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('898fa039-445b-5067-ad8b-08a4c659cb92', '18718368-5a15-50e7-a6c9-2ed686dcb440', 9, 'standard_conventions', 'boundaries', 'hard', 'mc', 'The storm closed the bridge for two days. Students _______ received a week''s extension; everyone else kept the original deadline.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":", who missed the deadline because of the storm,"},{"key":"B","text":"who missed the deadline because of the storm,"},{"key":"C","text":"who missed the deadline because of the storm"},{"key":"D","text":", who missed the deadline because of the storm"}]'::jsonb, 'C', null, '"Everyone else kept the original deadline" proves that only SOME students got the extension — so the clause is essential (it defines which students) and takes no commas. Choice A''s comma pair would claim all students missed the deadline, and B and D each carry a stray half-fence.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('63ebe006-d1e5-537f-ab30-08e0e843dd2b', '18718368-5a15-50e7-a6c9-2ed686dcb440', 10, 'standard_conventions', 'boundaries', 'hard', 'mc', 'The lighthouse keeper''s logbook, its pages warped by a century of salt _______ still records each night''s weather in a steady hand.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"air"},{"key":"B","text":"air,"},{"key":"C","text":"air;"},{"key":"D","text":"air —"}]'::jsonb, 'B', null, '"Its pages warped by a century of salt air" is a non-essential aside that opened with a comma after "logbook" — it must close with a comma so the subject can finally reach its verb, "records." The dash in choice D mixes fence types, and a semicolon would demand a complete sentence on each side.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('aa3ac183-f7af-5ac2-a876-60fe20a7650c', '18718368-5a15-50e7-a6c9-2ed686dcb440', 11, 'standard_conventions', 'boundaries', 'hard', 'mc', 'A bronze statue _______ stood at the harbor''s entrance for more than fifty years.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":", of the sun god Helios,"},{"key":"B","text":"of the sun god Helios,"},{"key":"C","text":", of the sun god Helios"},{"key":"D","text":"of the sun god Helios"}]'::jsonb, 'D', null, '"Of the sun god Helios" tells you which statue — essential information, no punctuation. The comma pair in choice A reads smoothly aloud, but fencing the phrase off claims the sentence would mean the same without it, and "A bronze statue stood at the harbor''s entrance" loses the very identity of the statue.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('95a2aead-00cd-54ab-a1c7-47c06311e9e0', '18718368-5a15-50e7-a6c9-2ed686dcb440', 12, 'standard_conventions', 'boundaries', 'hard', 'mc', 'Frida Kahlo''s childhood home — painted the deep cobalt that gave it its _______ is now a museum visited by thousands each week.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"name,"},{"key":"B","text":"name"},{"key":"C","text":"name —"},{"key":"D","text":"name;"}]'::jsonb, 'C', null, 'The aside opened with a dash, so only a dash can close it: "— painted the deep cobalt that gave it its name —". Choice A swaps in a comma, the most common mixed-fence trap on the test; lift the aside out and the frame "Kahlo''s childhood home is now a museum" confirms where the fences belong.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('89c385a9-55e7-5d5f-ae26-238fa3137e06', '18718368-5a15-50e7-a6c9-2ed686dcb440', 13, 'standard_conventions', 'boundaries', 'hard', 'mc', 'The flower festival _______ draws nearly a million visitors each spring.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"which began as a single flower cart in 1949,"},{"key":"B","text":", that began as a single flower cart in 1949,"},{"key":"C","text":", which began as a single flower cart in 1949"},{"key":"D","text":", which began as a single flower cart in 1949,"}]'::jsonb, 'D', null, 'The clause is extra history about a festival already identified, so it is non-essential: comma, "which," and a closing comma before the verb "draws." Choice B pairs a comma with "that" — never legal — and A and C each supply only half the fence.') on conflict (id) do nothing;
insert into public.tests (id, slug, title, subtitle, test_type, section_scope, focus_domain_id, difficulty, description, sort_order) values ('9c3f7ce4-0528-50fc-a603-c0338856c21a', 'week1-day3', 'Day 3 — Problem-solving and data', 'Week 1 · Problem-Solving and Data Analysis', 'drill', 'math', 'psda', 'mixed', 'Day 3 of this week''s practice. Read the card first, answer untimed, then read every explanation — right or wrong.', 103) on conflict (slug) do nothing;
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('bf4be541-a387-525c-aef8-4bc76905d03c', '9c3f7ce4-0528-50fc-a603-c0338856c21a', 1, 'Day 3 — Problem-solving and data', 'math', 1235) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('a8116e7b-3783-536c-aff2-073753bd6b2f', 'bf4be541-a387-525c-aef8-4bc76905d03c', 1, 'psda', 'percentages', 'easy', 'mc', null, 'A jacket regularly priced at $80 is on sale for 35% off the regular price. What is the sale price of the jacket?', '[{"key":"A","text":"$28"},{"key":"B","text":"$45"},{"key":"C","text":"$52"},{"key":"D","text":"$55"}]'::jsonb, 'C', null, '35% off means she pays 65%: 0.65 × 80 = $52. Choice A, $28, is the DISCOUNT (0.35 × 80) — the amount removed, not the price paid. That trap appears whenever a discount question is asked.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('8a136c0a-9df3-5473-a08f-6cf984f6e25c', 'bf4be541-a387-525c-aef8-4bc76905d03c', 2, 'psda', 'ratios_rates_proportions', 'easy', 'mc', null, 'A bread recipe uses flour and sugar in a ratio of 3 to 2 by weight. A baker uses 12 cups of flour. How many cups of sugar does the recipe require?', '[{"key":"A","text":"6"},{"key":"B","text":"8"},{"key":"C","text":"10"},{"key":"D","text":"18"}]'::jsonb, 'B', null, '12 cups of flour is 3 parts, so one part is 4 cups, and sugar is 2 parts: 8 cups. Choice D, 18, comes from applying the ratio upside down (12 × 3/2) — always check which quantity goes with which number in "3 to 2."') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('e490908c-dcc3-566a-ae2f-1e0d30382987', 'bf4be541-a387-525c-aef8-4bc76905d03c', 3, 'psda', 'ratios_rates_proportions', 'easy', 'spr', null, 'A bus travels 210 miles in 3.5 hours at a constant speed. What is the speed of the bus, in miles per hour?', null, '60', '[]'::jsonb, 'Rate = distance ÷ time = 210 ÷ 3.5 = 60 miles per hour. Type the amount and the time into Desmos rather than doing 3.5 in your head — half-hours are where slips happen.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('df357f59-1d4a-5fdc-aad6-0f9b7ac89d5f', 'bf4be541-a387-525c-aef8-4bc76905d03c', 4, 'psda', 'percentages', 'medium', 'mc', null, 'The population of a town grew from 2,400 to 3,000 over a decade. What was the percent increase in the town''s population?', '[{"key":"A","text":"25%"},{"key":"B","text":"20%"},{"key":"C","text":"30%"},{"key":"D","text":"600%"}]'::jsonb, 'A', null, 'Percent change divides by the ORIGINAL: (3,000 − 2,400) ÷ 2,400 = 600/2,400 = 25%. Choice B, 20%, divides by the new value (600/3,000) — the standard wrong divisor. D forgets to divide at all.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('9df88179-f397-54e2-acb3-b741aa278620', 'bf4be541-a387-525c-aef8-4bc76905d03c', 5, 'psda', 'percentages', 'medium', 'mc', null, 'After a 20% discount, a pair of shoes costs $44. What was the price of the shoes before the discount?', '[{"key":"A","text":"$52.80"},{"key":"B","text":"$48.00"},{"key":"C","text":"$50.00"},{"key":"D","text":"$55.00"}]'::jsonb, 'D', null, 'The sale price is 80% of the original, so original = 44 ÷ 0.80 = $55. Choice A, $52.80, is the trap: adding 20% back onto $44 (44 × 1.20). Taking 20% off $52.80 gives $42.24, not $44 — undoing a percent means dividing, never re-adding.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('ae000f0d-84b3-5235-abd6-f075fe140509', 'bf4be541-a387-525c-aef8-4bc76905d03c', 6, 'psda', 'ratios_rates_proportions', 'medium', 'spr', null, 'On a map, 2.5 centimeters represents 15 kilometers. Two towns are 8 centimeters apart on the map. What is the actual distance between the towns, in kilometers?', null, '48', '[]'::jsonb, 'Find the unit rate first: 15 ÷ 2.5 = 6 kilometers per centimeter, so 8 cm represents 8 × 6 = 48 km. Setting up the proportion 2.5/15 = 8/x works too; the error to avoid is flipping one side of it.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('287142ae-f6e2-5ac9-a6cd-19c282fc2f84', 'bf4be541-a387-525c-aef8-4bc76905d03c', 7, 'psda', 'one_var_data', 'medium', 'mc', null, 'On a 10-point quiz taken by 15 students, three students scored 6, five scored 7, four scored 8, and three scored 9. What is the median score?', '[{"key":"A","text":"7"},{"key":"B","text":"7.47"},{"key":"C","text":"7.5"},{"key":"D","text":"8"}]'::jsonb, 'A', null, 'With 15 scores, the median is the 8th value in order. Counting up: scores 1–3 are 6, scores 4–8 are 7 — so the 8th score is 7. Choice B, 7.47, is the MEAN (112 ÷ 15); the question asked for the median, and they differ here precisely because the data is not symmetric.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('5c2bfb09-47b1-5d69-a1af-153f2aabccc4', 'bf4be541-a387-525c-aef8-4bc76905d03c', 8, 'psda', 'probability', 'medium', 'mc', null, 'In a survey of 200 students, 120 play a sport. Of the 120 who play a sport, 45 also play an instrument. In total, 80 of the 200 students play an instrument. If a student who does NOT play a sport is chosen at random, what is the probability that the student plays an instrument?', '[{"key":"A","text":"3/8"},{"key":"B","text":"7/16"},{"key":"C","text":"7/40"},{"key":"D","text":"2/5"}]'::jsonb, 'B', null, 'The condition "does not play a sport" shrinks the world to 200 − 120 = 80 students, of whom 80 − 45 = 35 play an instrument: 35/80 = 7/16. Choice C, 35/200, uses the whole survey as the denominator — the words after "If" are what set the denominator.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('9905677c-7567-579e-acd9-521675bd62ce', 'bf4be541-a387-525c-aef8-4bc76905d03c', 9, 'psda', 'one_var_data', 'hard', 'mc', null, 'The mean of a gymnast''s five scores is 84. Her lowest score, a 62, is discarded and replaced by a new score of 92. What is the mean of the five scores after the replacement?', '[{"key":"A","text":"86"},{"key":"B","text":"88"},{"key":"C","text":"90"},{"key":"D","text":"92"}]'::jsonb, 'C', null, 'Work through the sum, not the scores: mean × count gives 84 × 5 = 420, the swap changes the sum by 92 − 62 = +30, and the new mean is 450 ÷ 5 = 90. Whenever a mean changes, convert to the total first — the individual scores are never needed.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('86e8a604-d2a6-5bfa-ae9c-9546d7229716', 'bf4be541-a387-525c-aef8-4bc76905d03c', 10, 'psda', 'sample_stats_moe', 'hard', 'mc', null, 'A polling organization surveys a random sample of a city''s residents and estimates that 54% support a new transit plan, with a margin of error of 4 percentage points. Which conclusion is best supported by these results?', '[{"key":"A","text":"The percentage of all residents who support the plan is plausibly between 50% and 58%."},{"key":"B","text":"Exactly 54% of the city''s residents support the plan."},{"key":"C","text":"About 4% of the residents surveyed are likely to change their minds."},{"key":"D","text":"The estimate is unreliable because the survey did not reach every resident."}]'::jsonb, 'A', null, 'A margin of error gives the plausible range for the true population value: 54 ± 4, so 50% to 58%. It does not make the point estimate exact (B), it says nothing about minds changing (C), and sampling instead of a census is not a flaw — it is the method the margin of error accounts for (D).') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('71c03e50-7023-5c37-a121-de7dc18202f8', 'bf4be541-a387-525c-aef8-4bc76905d03c', 11, 'psda', 'evaluating_claims', 'hard', 'mc', null, 'To estimate how many hours per week adults in a city exercise, a researcher surveys 300 people as they leave a gym and computes the average of their answers. Which statement best explains why this average is likely to be a poor estimate for all adults in the city?', '[{"key":"A","text":"The sample of 300 people is too small to compute an average."},{"key":"B","text":"The survey should have been conducted over several weeks."},{"key":"C","text":"People often round their answers to whole numbers of hours."},{"key":"D","text":"People leaving a gym are likely to exercise more than typical adults, so the sample overstates the citywide average."}]'::jsonb, 'D', null, 'The flaw is WHERE the sample was taken: gym-goers are not representative of all adults on the very trait being measured, biasing the estimate upward. A sample of 300 is plenty when it is random (A) — size cannot cure a biased location, which is exactly the distinction this question type tests.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('19293dd3-5e94-5370-aaea-bfde706e1c08', 'bf4be541-a387-525c-aef8-4bc76905d03c', 12, 'psda', 'two_var_data', 'hard', 'mc', null, 'For a streaming service, the line of best fit for subscribers over time is y = 3.2x + 17, where x is the number of years since 2010 and y is the number of subscribers in thousands. Which is the best interpretation of the number 3.2 in this context?', '[{"key":"A","text":"The service gained about 3.2 subscribers per year."},{"key":"B","text":"The service gained about 3,200 subscribers per year, on average."},{"key":"C","text":"The service gained about 17,000 subscribers per year."},{"key":"D","text":"The service has gained about 3,200 subscribers in total since 2010."}]'::jsonb, 'B', null, 'The slope is the predicted change in y for each 1-unit change in x — and since y is measured in THOUSANDS, 3.2 means about 3,200 subscribers per year. Choice A ignores the units of y, the detail these interpretation questions almost always turn on; 17 is the 2010 starting value, not a rate.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('1ffc988e-50f6-5803-a68d-e6d467ec0a55', 'bf4be541-a387-525c-aef8-4bc76905d03c', 13, 'psda', 'percentages', 'hard', 'spr', null, 'In a hiking club, 30% of the members are seniors, and 40% of the seniors have completed a first-aid course. What percent of the club''s members are seniors who have completed a first-aid course? (Enter your answer without the percent sign.)', null, '12', '[]'::jsonb, 'Successive percents multiply: 0.30 × 0.40 = 0.12, so 12% of all members. Adding to 70% or averaging to 35% are the planted errors — 40% here is 40% OF THE SENIORS, a percent of a percent.') on conflict (id) do nothing;
insert into public.tests (id, slug, title, subtitle, test_type, section_scope, focus_domain_id, difficulty, description, sort_order) values ('92459f1a-9498-5575-af05-d15b1ea0df97', 'week1-day4', 'Day 4 — Verbs, pronouns, transitions', 'Week 1 · Conventions + Transitions', 'drill', 'rw', 'standard_conventions', 'mixed', 'Day 4 of this week''s practice. Read the card first, answer untimed, then read every explanation — right or wrong.', 104) on conflict (slug) do nothing;
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('5aebfa29-78ab-5002-a8ef-d0fdec0afa1f', '92459f1a-9498-5575-af05-d15b1ea0df97', 1, 'Day 4 — Verbs, pronouns, transitions', 'rw', 923) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('426f13a3-0b44-596f-ab54-627738267201', '5aebfa29-78ab-5002-a8ef-d0fdec0afa1f', 1, 'standard_conventions', 'form_structure_sense', 'easy', 'mc', 'The pattern of stripes on a zebra''s hindquarters _______ as distinctive as a fingerprint.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"is"},{"key":"B","text":"are"},{"key":"C","text":"were"},{"key":"D","text":"have been"}]'::jsonb, 'A', null, 'Cross out the prepositional phrases and the subject is "The pattern" — singular, so "is." The plurals "stripes" and "hindquarters" sit right next to the blank to pull your ear toward "are"; that placement is deliberate.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('d0259943-1840-54aa-a5b5-b7091eeb176d', '5aebfa29-78ab-5002-a8ef-d0fdec0afa1f', 2, 'standard_conventions', 'form_structure_sense', 'easy', 'mc', 'By the time the fire crews arrived, the wind _______ the blaze across the ridge.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"has already pushed"},{"key":"B","text":"already pushes"},{"key":"C","text":"will already have pushed"},{"key":"D","text":"had already pushed"}]'::jsonb, 'D', null, '"By the time the crews arrived" sets two past events in order, and the earlier of two past events takes "had": the wind had pushed the blaze before the crews got there. "Has pushed" (choice A) connects past to present, which the past-tense "arrived" rules out.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('561dd17c-1f7f-5239-ad10-bf988bfd2ebb', '5aebfa29-78ab-5002-a8ef-d0fdec0afa1f', 3, 'standard_conventions', 'form_structure_sense', 'easy', 'mc', 'The museum rotates _______ collection every season so that fragile textiles are never displayed for long.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"it''s"},{"key":"B","text":"its"},{"key":"C","text":"their"},{"key":"D","text":"they''re"}]'::jsonb, 'B', null, '"Its" — no apostrophe — is the possessive; "it''s" always means "it is," and "The museum rotates it is collection" fails instantly if you expand it. A museum is a single institution, so the plural "their" is also wrong.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('0d36cfce-ab61-5b29-a7fd-a9b6854357cd', '5aebfa29-78ab-5002-a8ef-d0fdec0afa1f', 4, 'standard_conventions', 'form_structure_sense', 'medium', 'mc', 'When the archive opened in 1998, among the papers _______ a letter and two photographs no biographer had ever seen.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"was"},{"key":"B","text":"has been"},{"key":"C","text":"were"},{"key":"D","text":"is"}]'::jsonb, 'C', null, 'The sentence is inverted: the subject comes AFTER the verb, and it is compound — "a letter and two photographs" — so the verb is plural, "were." The singular "a letter" right after the blank baits "was"; find everything the verb governs before choosing.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('de26556b-2511-5c69-a711-4c0364302dbd', '5aebfa29-78ab-5002-a8ef-d0fdec0afa1f', 5, 'standard_conventions', 'form_structure_sense', 'medium', 'mc', 'The award went to the engineer _______ design cut the bridge''s cost nearly in half.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"who''s"},{"key":"B","text":"whom"},{"key":"C","text":"that"},{"key":"D","text":"whose"}]'::jsonb, 'D', null, 'The design belongs to the engineer, so the possessive "whose" is needed. "Who''s" means "who is" — expand it and "the engineer who is design" collapses. The apostrophe test (expand the contraction, see if the sentence survives) settles every who''s/whose and it''s/its question.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('80a75706-a0a6-583a-a977-112ff7f49ef3', '5aebfa29-78ab-5002-a8ef-d0fdec0afa1f', 6, 'standard_conventions', 'form_structure_sense', 'medium', 'mc', '_______ the manuscript''s faded ink finally became legible to the researchers.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"Illuminating the page with ultraviolet light,"},{"key":"B","text":"Illuminated by ultraviolet light,"},{"key":"C","text":"Having illuminated the page with ultraviolet light,"},{"key":"D","text":"After illuminating the page with ultraviolet light,"}]'::jsonb, 'B', null, 'An opening phrase must describe the next noun — "the manuscript''s faded ink." The ink WAS illuminated, so choice B fits; in A, C, and D the ink would have to be doing the illuminating, which it cannot. Ask of the noun after the comma: did it do this action, or receive it?') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('fccaf574-1967-5c39-a042-af2afb99aca2', '5aebfa29-78ab-5002-a8ef-d0fdec0afa1f', 7, 'standard_conventions', 'form_structure_sense', 'hard', 'mc', 'The number of active volcanoes on Jupiter''s moon Io _______ with each spacecraft flyby, as new eruptions are spotted on the surface.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"grow"},{"key":"B","text":"are growing"},{"key":"C","text":"grows"},{"key":"D","text":"have grown"}]'::jsonb, 'C', null, '"The number" is the subject, and "the number" is always singular: it grows. ("A number of volcanoes" would be plural.) The plural "volcanoes" parked next to the blank is there to mislead your ear.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('ec25c079-174d-52fe-a5b9-278f48e0996b', '5aebfa29-78ab-5002-a8ef-d0fdec0afa1f', 8, 'standard_conventions', 'form_structure_sense', 'hard', 'mc', 'The orchestra announced that _______ will tour East Asia next autumn with a program of new commissions.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"they"},{"key":"B","text":"them"},{"key":"C","text":"it"},{"key":"D","text":"those"}]'::jsonb, 'C', null, 'An orchestra — like a committee, museum, or company — is a single organization, so the pronoun is "it." "They" is what everyone says in conversation, which is exactly why the test keeps asking; in formal written English the institution stays singular.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('9b9f2941-9608-53b7-a198-38a810c653ab', '5aebfa29-78ab-5002-a8ef-d0fdec0afa1f', 9, 'standard_conventions', 'boundaries', 'hard', 'mc', 'The glacier has retreated more than two miles since _______ scientists attribute most of that change to a single unusually warm decade.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"1900,"},{"key":"B","text":"1900"},{"key":"C","text":"1900 and"},{"key":"D","text":"1900;"}]'::jsonb, 'D', null, 'Boundary review from Day 1: both sides of the blank are complete sentences, so only the semicolon can join them. The comma is a splice, nothing is a run-on, and "and" joining two independent clauses would still want a comma before it.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('5cc293fe-5f74-550b-a609-487e4c51d852', '5aebfa29-78ab-5002-a8ef-d0fdec0afa1f', 10, 'expression_ideas', 'transitions', 'easy', 'mc', 'Some animals use tools far more routinely than scientists once assumed. _______ sea otters crack open clams by pounding them against stones they balance on their chests.', 'Which choice completes the text with the most logical transition?', '[{"key":"A","text":"However,"},{"key":"B","text":"For instance,"},{"key":"C","text":"Therefore,"},{"key":"D","text":"Meanwhile,"}]'::jsonb, 'B', null, 'The first sentence makes a general claim and the second gives one case of it, so the transition must introduce an example: "For instance." "Therefore" would claim the otters'' behavior is a result of the first sentence, when it is really evidence for it.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('6e12bab6-b585-5347-aefe-d19ab3b4cc0b', '5aebfa29-78ab-5002-a8ef-d0fdec0afa1f', 11, 'expression_ideas', 'transitions', 'medium', 'mc', 'Early versions of the vaccine had to be stored at −70°C, a serious obstacle for rural clinics without reliable electricity. _______ researchers set out to develop a version that would stay stable in an ordinary refrigerator.', 'Which choice completes the text with the most logical transition?', '[{"key":"A","text":"Consequently,"},{"key":"B","text":"Similarly,"},{"key":"C","text":"For example,"},{"key":"D","text":"In other words,"}]'::jsonb, 'A', null, 'The storage problem is the reason the researchers acted, so the second sentence is a result of the first: "Consequently." "In other words" would mean the second sentence restates the first, but it reports a new action, not a rephrasing.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('7d2cd8a9-c792-57cc-ae50-5852164d4337', '5aebfa29-78ab-5002-a8ef-d0fdec0afa1f', 12, 'expression_ideas', 'transitions', 'medium', 'mc', 'Most drought-tolerant plants survive dry spells by storing water in thick stems or leaves. The resurrection fern, _______ stores almost none: it dries to a brittle brown curl and turns green again within a day of rain.', 'Which choice completes the text with the most logical transition?', '[{"key":"A","text":"in addition,"},{"key":"B","text":"as a result,"},{"key":"C","text":"by contrast,"},{"key":"D","text":"for instance,"}]'::jsonb, 'C', null, 'Most plants store water; this fern stores almost none — a direct contrast, so "by contrast." "For instance" is the trap: it would make the fern an EXAMPLE of plants that store water, the opposite of what the sentence says.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('845cc804-5179-54fe-a0be-73b71ae7805f', '5aebfa29-78ab-5002-a8ef-d0fdec0afa1f', 13, 'expression_ideas', 'transitions', 'hard', 'mc', 'The steam carriages of the 1830s were loud and slow, and at least one killed passengers when its boiler burst. _______ several of them carried paying passengers on regular routes around London for years.', 'Which choice completes the text with the most logical transition?', '[{"key":"A","text":"Even so,"},{"key":"B","text":"In fact,"},{"key":"C","text":"Likewise,"},{"key":"D","text":"Specifically,"}]'::jsonb, 'A', null, 'The first sentence lists serious drawbacks; the second reports success despite them — a concession, so "Even so." "In fact" is the trap: it signals that the second sentence strengthens the first, but regular paid service works against "loud, slow, and dangerous," not with it.') on conflict (id) do nothing;
insert into public.tests (id, slug, title, subtitle, test_type, section_scope, focus_domain_id, difficulty, description, sort_order) values ('1a1b180e-a958-5dbc-ab2c-a4a5fe662a6e', 'week1-day5', 'Day 5 — Words in context and structure', 'Week 1 · Craft and Structure', 'drill', 'rw', 'craft_structure', 'mixed', 'Day 5 of this week''s practice. Read the card first, answer untimed, then read every explanation — right or wrong.', 105) on conflict (slug) do nothing;
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('565f6f2f-6558-53f6-aef7-0b7588b696f4', '1a1b180e-a958-5dbc-ab2c-a4a5fe662a6e', 1, 'Day 5 — Words in context and structure', 'rw', 852) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('f33f1a74-e11a-5f90-aa1f-1ac4329b8b78', '565f6f2f-6558-53f6-aef7-0b7588b696f4', 1, 'craft_structure', 'words_in_context', 'easy', 'mc', 'Visitors often hesitate on the old rope bridge. Although its planks appear _______, the span beneath them was rebuilt with steel cable a decade ago and inspected again last spring.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"ornate"},{"key":"B","text":"fragile"},{"key":"C","text":"impervious"},{"key":"D","text":"immense"}]'::jsonb, 'B', null, '"Although" promises a contrast with the reassurance that follows — rebuilt with steel, recently inspected — so the planks must merely LOOK unsound: "fragile." "Impervious" (unable to be harmed) points the contrast the wrong way.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('7df544b6-4ce7-5f3b-a6b0-7d01894085a7', '565f6f2f-6558-53f6-aef7-0b7588b696f4', 2, 'craft_structure', 'words_in_context', 'easy', 'mc', 'The results of the small trial were _______: with only forty patients, the researchers stressed, nothing could be settled until a far larger study was run.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"preliminary"},{"key":"B","text":"conclusive"},{"key":"C","text":"irrelevant"},{"key":"D","text":"fabricated"}]'::jsonb, 'A', null, 'The colon restates the blank: nothing is settled yet and a larger study must follow — early-stage findings, i.e., "preliminary." "Conclusive" says the opposite of the clue, and nothing suggests the results were faked or beside the point.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('f234630a-f499-55a8-a0cd-e4a2103373ab', '565f6f2f-6558-53f6-aef7-0b7588b696f4', 3, 'craft_structure', 'words_in_context', 'medium', 'mc', 'Rather than confronting the objection directly, the senator''s reply merely _______ it, turning to the next question as though the challenge had never been raised.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"bolstered"},{"key":"B","text":"refuted"},{"key":"C","text":"echoed"},{"key":"D","text":"sidestepped"}]'::jsonb, 'D', null, '"Rather than confronting... directly" and "as though the challenge had never been raised" both point to avoidance: "sidestepped." "Refuted" — disproved — would be a form of direct confrontation, exactly what the sentence denies.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('2c2b25d4-51f6-547f-aa1d-e6879e9ea773', '565f6f2f-6558-53f6-aef7-0b7588b696f4', 4, 'craft_structure', 'words_in_context', 'medium', 'mc', 'The sailor''s account of a great flood, long dismissed as legend, was finally _______ by sediment cores from the lake bed, which record a massive inundation around the very decade he described.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"contradicted"},{"key":"B","text":"anticipated"},{"key":"C","text":"corroborated"},{"key":"D","text":"embellished"}]'::jsonb, 'C', null, 'The cores record the flood in the very decade the sailor described — physical evidence confirming the account, i.e., "corroborated" it. The clue "long dismissed as legend... finally" signals vindication, ruling out "contradicted."') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('20e19bf7-2074-519f-a2e4-15eaa2602762', '565f6f2f-6558-53f6-aef7-0b7588b696f4', 5, 'craft_structure', 'words_in_context', 'medium', 'mc', 'The difference in fuel use between the two engine designs proved _______ — a fraction of a percent, far too small to justify the expense of retooling the whole assembly line.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"negligible"},{"key":"B","text":"substantial"},{"key":"C","text":"ambiguous"},{"key":"D","text":"deliberate"}]'::jsonb, 'A', null, 'The dash restates the blank: "a fraction of a percent, far too small to justify..." — so small it can be ignored, which is precisely "negligible." "Ambiguous" would mean unclear, but the measurement is perfectly clear; it is just tiny.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('fe433ee6-bade-57b9-a4bb-8dafb1a66c07', '565f6f2f-6558-53f6-aef7-0b7588b696f4', 6, 'craft_structure', 'words_in_context', 'medium', 'mc', 'Cutting back the reed beds was meant to control the seasonal flooding, but the work actually _______ it: the plants'' dense roots, it turned out, had been anchoring the banks in place.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"mitigated"},{"key":"B","text":"exacerbated"},{"key":"C","text":"obscured"},{"key":"D","text":"preceded"}]'::jsonb, 'B', null, '"But" reverses the stated intention (control the flooding), and the roots had been holding the banks — so removing them made flooding WORSE: "exacerbated." "Mitigated" is the intended outcome the sentence explicitly overturns.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('cce08dc8-8180-5488-ac0a-81e1abd73fac', '565f6f2f-6558-53f6-aef7-0b7588b696f4', 7, 'craft_structure', 'text_structure_purpose', 'medium', 'mc', 'For decades, textbooks described the deep seafloor as a biological desert, too dark and cold to support much life. Then, in 1977, a submersible crew surveying a volcanic ridge found hot vents crowded with giant tube worms, clams, and pale crabs. The discovery forced biologists to accept that whole ecosystems could run on chemical energy rather than sunlight.', 'Which choice best describes the function of the second sentence in the text as a whole?', '[{"key":"A","text":"It offers an example that supports the textbook description mentioned in the first sentence."},{"key":"B","text":"It explains why the deep seafloor is too dark and cold to support much life."},{"key":"C","text":"It presents the observation that overturned the view described in the first sentence."},{"key":"D","text":"It concedes a weakness in the biologists'' new understanding of deep-sea ecosystems."}]'::jsonb, 'C', null, 'Sentence one states the old view (a biological desert), sentence two reports the 1977 find that contradicts it, and sentence three names the consequence. The second sentence''s job is the overturning observation — it challenges the first sentence, not supports it.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('c8ff608d-2a98-55a8-a36e-3ce8904f4da6', '565f6f2f-6558-53f6-aef7-0b7588b696f4', 8, 'craft_structure', 'text_structure_purpose', 'medium', 'mc', 'Monarch butterfly counts at Mexican wintering sites have fallen sharply over thirty years. Some researchers blame the loss of milkweed — the caterpillars'' only food — along North American migration routes; others point to logging in the mountain forests where the butterflies overwinter. A new tagging program that tracks individual butterflies across the whole journey may soon reveal which pressure matters more.', 'Which choice best describes the overall structure of the text?', '[{"key":"A","text":"A hypothesis is proposed, tested, and ultimately rejected."},{"key":"B","text":"A phenomenon is described, and two competing explanations for it are presented."},{"key":"C","text":"Two studies are summarized, and the methods of both are criticized."},{"key":"D","text":"A prediction is made and then confirmed by new evidence."}]'::jsonb, 'B', null, 'The structure is: decline (phenomenon) → milkweed loss vs. logging (two rival explanations) → a program that may decide between them. Nothing is rejected, criticized, or confirmed yet — choices A, C, and D each describe a resolution the passage never reaches.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('c28b591f-519f-5419-a93a-fcafedab0fed', '565f6f2f-6558-53f6-aef7-0b7588b696f4', 9, 'craft_structure', 'words_in_context', 'hard', 'mc', 'The proposed link between the two anonymous manuscripts rests on a single shared phrase — a common proverb of the period — so many scholars consider the attribution _______.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"indisputable"},{"key":"B","text":"redundant"},{"key":"C","text":"prolific"},{"key":"D","text":"tenuous"}]'::jsonb, 'D', null, 'One shared phrase, and a commonplace proverb at that, is the thinnest possible evidence — the link is weak, or "tenuous." The aside "a common proverb of the period" actively undercuts the evidence, so "indisputable" inverts the logic.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('0e56e9f7-8209-5984-a1ad-71c8b1d28cfb', '565f6f2f-6558-53f6-aef7-0b7588b696f4', 10, 'craft_structure', 'words_in_context', 'hard', 'mc', 'The memoir''s narrator is _______ toward the tradition she was raised in: she records its ceremonies in loving detail even as she questions, on nearly every page, the demands they place on the women of her family.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"ambivalent"},{"key":"B","text":"indifferent"},{"key":"C","text":"hostile"},{"key":"D","text":"oblivious"}]'::jsonb, 'A', null, 'She loves the ceremonies AND questions their demands — two opposed feelings held at once, which is "ambivalent." The trap is "indifferent," which many students read as a synonym; it actually means she wouldn''t care at all, the opposite of feeling both things strongly.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('97ced24d-cbeb-5a24-aa27-c108f3c56efc', '565f6f2f-6558-53f6-aef7-0b7588b696f4', 11, 'craft_structure', 'text_structure_purpose', 'hard', 'mc', 'The narrator had not meant to stop at the house at all. But the gate stood open, and the smell of rain on the garden was the smell of every summer she had spent there, and before she had decided anything her hand was on the latch. Inside, the rooms were smaller than memory insisted, yet each one, as she entered it, returned something she had not known was missing.', 'Which choice best states the main purpose of the text?', '[{"key":"A","text":"To describe the architectural details of a house the narrator once lived in"},{"key":"B","text":"To explain why the narrator became estranged from her childhood home"},{"key":"C","text":"To argue that childhood memories are usually unreliable"},{"key":"D","text":"To convey how returning to a childhood place revives the narrator''s buried memories"}]'::jsonb, 'D', null, 'Everything drives toward the final clause — each room "returned something she had not known was missing" — a place calling back lost memories. The rooms being "smaller than memory insisted" is a passing detail, not the purpose, so choice A mistakes scenery for point.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('0d052e1c-345c-5e98-a1a5-d7b66cbae520', '565f6f2f-6558-53f6-aef7-0b7588b696f4', 12, 'craft_structure', 'text_structure_purpose', 'hard', 'mc', 'Print, the argument goes, is finished. Yet though screens have improved markedly — today''s best displays are easier on the eyes than a paperback in dim light — surveys keep finding that students remember more of what they read on paper. The technology that was supposed to replace the book may instead have clarified what the book does well.', 'Which choice best describes the function of the phrase set off by dashes in the text?', '[{"key":"A","text":"It provides evidence that students remember more of what they read on screens."},{"key":"B","text":"It explains why surveys of student reading are unreliable."},{"key":"C","text":"It acknowledges a genuine strength of screens before the text reasserts print''s advantage."},{"key":"D","text":"It argues that paperbacks are poorly designed for reading in dim light."}]'::jsonb, 'C', null, 'The aside grants the other side a real point — screens have gotten good — which makes the survey finding that follows more persuasive, not less. That move is concession; choice A misreads the aside as evidence for screens'' memory advantage, which the passage never claims.') on conflict (id) do nothing;
insert into public.tests (id, slug, title, subtitle, test_type, section_scope, focus_domain_id, difficulty, description, sort_order) values ('3d8715fe-bbe6-58d3-a537-e537b5c32d84', 'week1-day6', 'Day 6 — Evidence and inferences', 'Week 1 · Information and Ideas', 'drill', 'rw', 'information_ideas', 'mixed', 'Day 6 of this week''s practice. Read the card first, answer untimed, then read every explanation — right or wrong.', 106) on conflict (slug) do nothing;
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('7d0fd368-944b-58b5-a6bf-6af426e4baf8', '3d8715fe-bbe6-58d3-a537-e537b5c32d84', 1, 'Day 6 — Evidence and inferences', 'rw', 852) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('5f7622ed-22bb-511a-a10e-787add564e01', '7d0fd368-944b-58b5-a6bf-6af426e4baf8', 1, 'information_ideas', 'central_ideas_details', 'easy', 'mc', 'My aunt could read a whole family in a basket of mending: the carefully kept cuffs of a man starting a new job, a hem let down for a daughter grown two inches by spring, the neat patches of a household stretching one coat across two winters. She rarely asked her customers questions. The clothes, she said, had already answered them.', 'Which choice best states the main idea of the text?', '[{"key":"A","text":"The narrator''s aunt preferred mending clothes to making new ones."},{"key":"B","text":"Through the clothes she repaired, the narrator''s aunt came to know her customers'' lives."},{"key":"C","text":"The narrator''s aunt was too shy to speak with the customers who visited her shop."},{"key":"D","text":"Mending clothes was once a common way for families to save money."}]'::jsonb, 'B', null, 'The frame is the first clause — she "could read a whole family in a basket of mending" — and the closing line repeats it: the clothes answered her questions. Choice C mistakes her not needing to ask for shyness, and D turns one example (the stretched coat) into the whole point.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('a34e4ed3-fccc-5129-a014-bd3d5425d22b', '7d0fd368-944b-58b5-a6bf-6af426e4baf8', 2, 'information_ideas', 'evidence_quantitative', 'easy', 'mc', 'A coastal reserve reported 120 breeding pairs of terns in 2015, 180 pairs in 2020, and 195 pairs in 2025. The reserve''s directors claim that although the colony is still growing, its growth has slowed markedly since 2020.', 'Which choice best describes how the data support the directors'' claim?', '[{"key":"A","text":"The colony held more breeding pairs in 2015 than in 2025."},{"key":"B","text":"The reserve added 60 pairs between 2015 and 2020 but only 15 between 2020 and 2025."},{"key":"C","text":"The number of breeding pairs nearly doubled between 2020 and 2025."},{"key":"D","text":"The colony stopped growing entirely after 2020."}]'::jsonb, 'B', null, 'The claim has two parts — still growing, but more slowly — and choice B captures both: +60 in the first five years, +15 in the next five. Choice D overshoots the claim (growth slowed; it did not stop), the standard exaggeration trap on data questions.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('0c0d8c31-38ac-5d72-ad9f-4642a67e662c', '7d0fd368-944b-58b5-a6bf-6af426e4baf8', 3, 'information_ideas', 'central_ideas_details', 'medium', 'mc', 'Rooftop beehives have become a badge of urban sustainability, and cities from Berlin to Toronto now host thousands. But honeybees are managed livestock, not endangered wildlife, and they forage on the same flowers as wild bees. Surveys in Paris found that plots near dense clusters of hives hosted fewer wild bee species than similar plots farther away. Some ecologists now argue that a city serious about pollinators should count its flowers before adding hives.', 'Which choice best states the main idea of the text?', '[{"key":"A","text":"Honeybees are the most important pollinators in most large cities."},{"key":"B","text":"Cities such as Berlin and Toronto host more rooftop hives than Paris does."},{"key":"C","text":"Urban beekeeping, though popular, may harm the wild pollinators it is assumed to help."},{"key":"D","text":"Wild bees should be relocated away from cities with many rooftop hives."}]'::jsonb, 'C', null, 'Every sentence builds one argument: hives are fashionable, but honeybees compete with wild bees, the Paris surveys show harm, and ecologists urge caution. Choice B promotes a passing detail to the main idea, and D proposes an action the passage never mentions.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('87bcf6cb-c4ff-5c8f-ad4f-468f6b97f226', '7d0fd368-944b-58b5-a6bf-6af426e4baf8', 4, 'information_ideas', 'evidence_textual', 'medium', 'mc', 'Historians long puzzled over how Pacific Islander navigators crossed thousands of miles of open ocean without instruments. Oral traditions describe steering by the feel of ocean swells, which bend and reflect around islands in characteristic patterns. A research team studying these traditions claims that swell patterns alone could reveal the direction of an island well before it became visible.', 'Which finding, if true, would most strongly support the research team''s claim?', '[{"key":"A","text":"In trials at sea, master navigators lying blindfolded in a canoe''s hull correctly identified the bearing of nearby islands from wave motion alone."},{"key":"B","text":"Historical records show that Pacific voyaging canoes were larger and faster than researchers once believed."},{"key":"C","text":"Many Pacific navigators also memorized the positions of hundreds of stars."},{"key":"D","text":"Some islands in the Pacific are surrounded by reefs that alter local currents."}]'::jsonb, 'A', null, 'The claim is that swells ALONE could reveal an island''s direction — and blindfolded navigators doing exactly that is the claim demonstrated. Choice C is true-sounding and on-topic but supports a different method (stars), which is why it tempts; it says nothing about what swells alone can do.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('059c6eb0-0d0a-56d2-ade4-de96b2051230', '7d0fd368-944b-58b5-a6bf-6af426e4baf8', 5, 'information_ideas', 'inferences', 'medium', 'mc', 'By 1990, an automated lamp could run a lighthouse far more cheaply than a resident keeper. Yet Canada kept staff at dozens of stations, citing duties no lamp performs: radioing weather to fishing boats, spotting capsized kayakers, logging whale strandings. For these stations, the case for keeping keepers rested less on the light itself than on _______', 'Which choice most logically completes the text?', '[{"key":"A","text":"the rising cost of maintaining automated lamps."},{"key":"B","text":"the fear that automated lamps would prove unreliable in storms."},{"key":"C","text":"the tradition and romance associated with lighthouse keeping."},{"key":"D","text":"the other services a person stationed at the site could provide."}]'::jsonb, 'D', null, 'The passage lists exactly what the lamp cannot do — radio weather, spot kayakers, log strandings — all services of a PERSON on site, so the conclusion must name them. Choice C is plausible in the real world, but the passage cites duties, not romance; the completion must follow from the listed evidence.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('c9695700-f58e-5949-a903-a3fd54ecaea6', '7d0fd368-944b-58b5-a6bf-6af426e4baf8', 6, 'information_ideas', 'inferences', 'medium', 'mc', 'The Svalbard seed vault preserves duplicate seeds from the world''s crop collections by drying and deep-freezing them. But the seeds of some crops — coconut, cacao, and many tropical fruits — are killed by drying and cannot be frozen. For those species, botanists must instead maintain living orchards, which are vulnerable to storms and disease. A truly global backup system for crop diversity therefore cannot rely on _______', 'Which choice most logically completes the text?', '[{"key":"A","text":"collecting seeds from wild plants as well as cultivated ones."},{"key":"B","text":"orchards planted in regions with frequent storms."},{"key":"C","text":"a single preservation method suited to only some species."},{"key":"D","text":"seed vaults located in cold northern climates."}]'::jsonb, 'C', null, 'The logic: freezing works for many crops, fails for some, and the alternative (orchards) is fragile — so no ONE method covers everything. Choice D is narrower than the argument: the problem shown is not Svalbard''s location but the freezing method itself, which would fail for coconut anywhere.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('ab890bb1-71ed-51aa-a298-a5cec9b472d7', '7d0fd368-944b-58b5-a6bf-6af426e4baf8', 7, 'information_ideas', 'evidence_textual', 'hard', 'mc', 'Excavating a Roman villa in southern Britain, archaeologists uncovered an elaborate floor mosaic. Because the villa was modest in other respects, the team concluded that the mosaic was the work of local artisans imitating Mediterranean fashions rather than of specialists brought from abroad.', 'Which finding, if true, would most directly weaken the team''s conclusion?', '[{"key":"A","text":"Several other villas in southern Britain contain mosaics of similar size."},{"key":"B","text":"The villa''s owners appear to have imported wine and olive oil from Italy."},{"key":"C","text":"Local workshops in Roman Britain are known to have produced high-quality pottery."},{"key":"D","text":"The mosaic''s laying technique matches a method taught only in workshops near Alexandria."}]'::jsonb, 'D', null, 'If the technique was taught only near Alexandria, the makers were almost certainly trained specialists from abroad — striking directly at "local artisans." Choice B shows imported GOODS, but the conclusion is about the makers of the mosaic; importing wine says nothing about who laid the floor.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('69704225-54b5-598d-a129-f75551ed635c', '7d0fd368-944b-58b5-a6bf-6af426e4baf8', 8, 'information_ideas', 'evidence_quantitative', 'hard', 'mc', 'A university surveyed its students about commuting. In 2015, 40 percent of the 500 students surveyed said they biked to campus. In 2025, 30 percent of the 900 students surveyed said the same.', 'Which statement is best supported by the data in the text?', '[{"key":"A","text":"The share of surveyed students who biked fell, even though the number who biked rose."},{"key":"B","text":"Fewer surveyed students biked to campus in 2025 than in 2015."},{"key":"C","text":"Biking to campus became more popular among surveyed students between 2015 and 2025."},{"key":"D","text":"The number of surveyed students who biked fell, even though the share who biked rose."}]'::jsonb, 'A', null, 'Compute both quantities: the share fell from 40% to 30%, but the count rose from 0.40 × 500 = 200 to 0.30 × 900 = 270. Percentages and counts can move in opposite directions when the total changes — choice B trusts the falling percent without ever computing the counts.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('7211bc35-6943-564d-aed2-14e0b52567f5', '7d0fd368-944b-58b5-a6bf-6af426e4baf8', 9, 'information_ideas', 'inferences', 'hard', 'mc', 'Unlike modern concrete, which slowly cracks apart in seawater, the concrete of Roman harbors grew stronger over centuries: seawater reacting with the mixture formed interlocking minerals that sealed each new crack. Engineers hoping to reproduce the effect note that the key ingredient, a particular volcanic ash, occurs in quantity only near certain volcanoes. Reviving the Roman recipe for wide use will therefore first require _______', 'Which choice most logically completes the text?', '[{"key":"A","text":"identifying substitute materials that behave the way the Romans'' ash did."},{"key":"B","text":"protecting the remaining Roman harbors from modern shipping."},{"key":"C","text":"convincing engineers that modern concrete is obsolete."},{"key":"D","text":"building new harbors only near active volcanoes."}]'::jsonb, 'A', null, 'The obstacle the passage sets up is scarcity of the one key ingredient, so wide use demands something that does the same job — a substitute. Choice D takes the constraint literally instead of solving it, and B and C answer questions the passage never raises.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('eec90c87-8dcd-5975-a72f-93401a04f81d', '7d0fd368-944b-58b5-a6bf-6af426e4baf8', 10, 'information_ideas', 'evidence_textual', 'hard', 'mc', 'In an early twentieth-century poem, the speaker has spent her life on her family''s farm. A literary critic claims that the poem presents the speaker as bound to the farm even while she longs to leave it.', 'Which quotation from the poem most effectively illustrates the critic''s claim?', '[{"key":"A","text":"\"The barn stands gray, and I no longer care / what wind unmakes it, board by silvered board.\""},{"key":"B","text":"\"Each furrow holds my name; each gate I open / opens upon a road I will not take.\""},{"key":"C","text":"\"The city called, and I went singing / down the bright road, without one backward glance.\""},{"key":"D","text":"\"My mother plowed, her mother plowed before her; / the field remembers each of us by name.\""}]'::jsonb, 'B', null, 'The claim has two halves — bound AND longing — and only choice B holds both: the furrows own her name (bound) while the opened gate shows a road she will not take (longing denied). Choice C shows leaving without regret, and D shows only belonging; each captures half the claim, which is not enough.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('cd79565c-7d04-5109-a125-97cbf50ca666', '7d0fd368-944b-58b5-a6bf-6af426e4baf8', 11, 'information_ideas', 'inferences', 'hard', 'mc', 'Historians of trade usually rely on customs documents, which record what merchants declared they were shipping. A team studying eighteenth-century Atlantic commerce has begun instead analyzing residues absorbed into the clay of shipping jars, which record what the jars actually held. Documents can be falsified by anyone hoping to avoid a tax; residues cannot. When the two sources disagree about a cargo, _______', 'Which choice most logically completes the text?', '[{"key":"A","text":"historians should assume the customs documents were copied incorrectly."},{"key":"B","text":"the disagreement shows that residue analysis is still too unreliable to use."},{"key":"C","text":"the jars were probably reused for many different cargoes over the years."},{"key":"D","text":"the residues may expose goods that the paperwork deliberately concealed."}]'::jsonb, 'D', null, 'The passage stacks the deck: documents can be falsified to dodge taxes, residues cannot — so a mismatch points to hidden cargo, exactly choice D''s modest "may expose." Choice B reverses the passage''s stated reliability ranking, and C introduces an explanation the text never offers.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('ef601b13-9835-5fbc-a30e-fb6fce21e587', '7d0fd368-944b-58b5-a6bf-6af426e4baf8', 12, 'information_ideas', 'central_ideas_details', 'hard', 'mc', 'For a century, brewers assumed lager yeast had simply arisen in the cold cellars of Bavaria, where the style was born. Genome sequencing told a stranger story: lager yeast is a hybrid, and one of its two parent species was entirely unknown to science until 2011, when it was found growing on tree bark in Patagonia. Wild relatives have since turned up in Tibet and North America, and how the species reached fifteenth-century Bavaria is still debated.', 'Which choice best states the main idea of the text?', '[{"key":"A","text":"Lager brewing began in Bavaria in the fifteenth century."},{"key":"B","text":"Genome sequencing has replaced older methods of studying yeast."},{"key":"C","text":"Genetic evidence gave lager yeast an unexpectedly distant origin that remains only partly explained."},{"key":"D","text":"Wild yeast from Tibet was used in the first Bavarian lagers."}]'::jsonb, 'C', null, 'The passage''s arc is assumption (born in Bavaria) → genetic surprise (a parent species first found in Patagonia) → open question (how it traveled), and choice C spans all three. Choice A inflates a supporting detail, D claims an answer the passage says is still debated, and B mistakes the tool for the finding.') on conflict (id) do nothing;
